<script setup>
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {setCourseExperience} from '../composables/experience'
import {api} from '../api'
import {SlidersHorizontal} from '@lucide/vue'
import CourseQuestions from '../components/CourseQuestions.vue'
import {courseSections} from '../utils/courseNavigation'
import LearningHistoryView from './LearningHistoryView.vue'
import CourseTools from '../components/CourseTools.vue'
import CourseRoster from '../components/CourseRoster.vue'
import AssessmentsView from './AssessmentsView.vue'
import GradebookPanel from '../components/GradebookPanel.vue'
import CourseUnits from '../components/CourseUnits.vue'
const route=useRoute(),router=useRouter(),course=ref(null),error=ref(''),loading=ref(true),tools=ref(null),courseForm=ref(null),saving=ref(false)
const statistics=ref(null)
const sections=computed(()=>course.value?courseSections(course.value):[])
const section=computed(()=>sections.value.some(s=>s.key===route.query.section)?route.query.section:'home')
const staff=computed(()=>['teacher','ta'].includes(course.value?.courseRole))
async function load(){try{course.value=await api(`/courses/${route.params.courseId}`);setCourseExperience(course.value.canPractice)}catch(e){error.value=e.message}finally{loading.value=false}}
async function activate(){try{await api('/courses/'+course.value.id+'/activate',{method:'POST'});await changed()}catch(e){error.value=e.message}}
async function changed(){try{course.value=await api(`/courses/${route.params.courseId}`);await tools.value?.reload()}catch(e){error.value=e.message}}
function editCourse(){courseForm.value={code:course.value.code,title:course.value.title,termCode:course.value.termCode,classLabel:course.value.classLabel,expectedVersion:course.value.version}}
async function saveCourse(){saving.value=true;error.value='';try{await api('/courses/'+course.value.id,{method:'PUT',body:courseForm.value});courseForm.value=null;await changed()}catch(e){error.value=e.message}finally{saving.value=false}}
async function archive(){if(!confirm('封存課程後將停止教學管理修改，但保留學員、作答、成績及稽核紀錄。確定封存？'))return;try{await api('/courses/'+course.value.id+'/archive',{method:'POST'});await changed()}catch(e){error.value=e.message}}
async function removeCourse(){if(!confirm('只有完全空白的草稿課程可以刪除。確定嘗試刪除？'))return;try{await api('/courses/'+course.value.id,{method:'DELETE'});await router.replace('/courses')}catch(e){error.value=e.message}}
watch(()=>route.fullPath,()=>{if(course.value)setCourseExperience(course.value.canPractice)})
watch([section,staff],async([key,isStaff])=>{
 if(key==='history'&&isStaff)try{statistics.value=await api('/courses/'+course.value.id+'/statistics')}catch(e){error.value=e.message}
})
onMounted(load)
</script>
<template><RouterLink to="/courses" class="back-link">← 返回我的課程</RouterLink><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="loading" class="empty-inline">載入課程中…</p><template v-if="course"><section class="page-heading"><div><p class="eyebrow">{{course.code}} · {{course.termCode}} {{course.classLabel}}</p><h1>{{course.title}}</h1><p class="muted">本課程的教材、學員與評量集中於此。{{{teacher:'授課教師',ta:'課程助教',student:'學生'}[course.courseRole]}}</p></div><div class="course-heading-actions"><RouterLink v-if="staff&&section==='home'" :to="{path:route.path,query:{section:'settings'}}" class="icon-button course-settings-link" aria-label="進入課程設定" title="課程設定"><SlidersHorizontal :size="20" /></RouterLink><span class="status-badge">{{{draft:'草稿',active:'進行中',archived:'已封存'}[course.status]}}</span></div></section><div class="course-detail-strip"><span>{{course.studentCount}} 位學員</span><span>{{course.resourceCount}} 份教材</span><span>{{course.quizCount}} 份測驗</span><span>{{course.reportCount}} 份 PDF 作業</span></div><template v-if="section==='home'"><section class="surface form-surface"><h2>課程首頁</h2><p>{{staff?'依單元安排教材、測驗與作業，再進入各活動管理內容。':'請依課程單元完成教材、測驗與作業。'}}</p><RouterLink :to="{query:{section:'units'}}">查看課程單元 →</RouterLink></section><CourseUnits :course="course" /></template><CourseUnits v-if="section==='units'" :course="course" :manage="staff" @changed="changed"/><template v-if="section==='history'"><LearningHistoryView v-if="!staff&&!course.canPractice" :bound-course="course.id"/><p v-else-if="!staff">學生視角預覽沒有個人學習紀錄。</p><section v-else class="surface form-surface"><h2>本課學習統計</h2><dl v-if="statistics"><dt>有效修課學生</dt><dd>{{statistics.enrolled}} 人</dd><dt>已正式提交測驗或報告</dt><dd>{{statistics.submitters}} 人，共 {{statistics.submissions}} 份</dd><dt>已有有效教材學習時間</dt><dd>{{statistics.materialLearners}} 人</dd></dl><RouterLink :to="{query:{section:'resources'}}">逐份查看教材參與紀錄</RouterLink></section></template><CourseQuestions v-if="section==='questions'" :key="course.id" :course="course" /><section v-if="section==='settings'&&staff" class="surface form-surface"><h2><SlidersHorizontal :size="20" /> 課程設定</h2><button v-if="course.isOwner&&course.status==='draft'" class="button primary" @click="activate">開放課程給學生</button><p>管理本課程的基本資料、學員、單元與教學內容。</p><template v-if="course.isOwner"><button v-if="!courseForm&&course.status!=='archived'" class="button secondary" @click="editCourse">編輯課程資料</button><form v-if="courseForm" class="question-editor" @submit.prevent="saveCourse"><fieldset :disabled="saving"><div class="form-grid"><label>課程代碼<input v-model="courseForm.code" required maxlength="40"/></label><label>課程名稱<input v-model="courseForm.title" required maxlength="200"/></label><label>學期<input v-model="courseForm.termCode" required maxlength="40"/></label><label>班別顯示<input v-model="courseForm.classLabel" maxlength="80"/></label></div><button class="button primary">儲存課程</button> <button type="button" class="button secondary" @click="courseForm=null">取消</button></fieldset></form><div v-if="course.status!=='archived'" class="course-lifecycle"><button class="button danger" @click="archive">封存課程</button><button v-if="course.status==='draft'" class="button secondary" @click="removeCourse">刪除空白草稿</button><p class="field-hint">有學員、單元、教材、作答或成績的課程不可直接刪除；封存會完整保留歷史。</p></div></template><RouterLink :to="{path:route.path,query:{section:'students'}}" class="button secondary">學員與小組設定</RouterLink><RouterLink :to="{path:route.path,query:{section:'units'}}" class="button secondary">單元管理</RouterLink><RouterLink :to="{path:route.path,query:{section:'resources'}}" class="button secondary">教材管理</RouterLink><RouterLink :to="{path:route.path,query:{section:'assessments'}}" class="button secondary">測驗與作業設定</RouterLink></section><CourseTools v-if="section==='resources'" :course="course" :staff="staff" section="resources" @changed="changed" /><CourseRoster v-if="section==='students'&&staff" :course="course" @changed="changed"/><CourseTools v-if="section==='groups'" ref="tools" :course="course" :staff="staff" section="groups"/><AssessmentsView v-if="['review','assessments'].includes(section)" :key="section" :review-only="section==='review'" embedded :bound-course="course" /><GradebookPanel v-if="section==='grades'" :course="course" /></template></template>

<style scoped>.course-heading-actions{display:flex;align-items:center;gap:10px}.course-settings-link{border:1px solid var(--line);background:var(--surface);color:var(--accent)}.course-settings-link:hover{background:var(--accent-soft);border-color:var(--accent)}.course-lifecycle{margin:18px 0;padding:16px;border:1px solid color-mix(in srgb,var(--danger) 28%,var(--line));border-radius:9px}.course-lifecycle .button{margin-right:8px}.button.danger{background:var(--danger);color:white}</style>
